local ADDON, ns = ...
local L = ns.L

-- The duty letters (RoleBriefings.lua): the Shogun's letter for each office a character holds, the
-- launch letter, the guild master's letter with its checklist and the Apostles' launch letter. In
-- the Shogun's own voice (the author's rule for every letter signed "- The Shogun": short, plain, a
-- little funny, never a herald's). The signature is L.HONOR_LETTER_SIGN, never repeated in a body.
-- A body is paragraphs split by a blank line; a line that starts with "- " is one item of a list.
-- %s: the guild's name (or, for a missionary, his network's Apostle), where a letter has one.

-- The page and its links.
L.RB_PAGE_TITLE = "Letters for your offices"
L.RB_PAGE_NOTE = "One letter from the Shogun for each office this character holds, the first time it holds it. They stay here, and under My profile > Letters, to reread."
