	L.RB_GM_LEGATES_JOB = "Cada um lidera um grupo de raide: ele e até 39 companheiros de guilda que toparam, 40 no total."
	L.RB_GM_LEGATES_SHOWS = "O badge de Legate no retrato dele, e o mesmo badge ao lado do nome."
