	L.RB_GM_ARTISANRY_SHOWS = "O badge da Associação dos Artesãos no retrato e ao lado do nome."
	L.RB_GM_ARTISANRY_UNLOCKS = "Um atalho para o quadro de Artesãos, e a sala dos Artesãos. Ainda sem poder extra."
	L.RB_GM_HERALDRY = "Correspondente do Departamento de Heráldica"
	L.RB_GM_HERALDRY_JOB = "Cuida dos decretos, da Agenda e das convocações da guilda, e faz o pessoal aparecer."
	L.RB_GM_HERALDRY_SHOWS = "O badge do Departamento de Heráldica no retrato e ao lado do nome."
	L.RB_GM_HERALDRY_UNLOCKS = "Todo tipo de decreto e a Agenda, só para a sua guilda. A sala da Heráldica."
	L.RB_GM_CHURCHDEPT = "Correspondente da Igreja Missionária (a aba Guilda)"
	L.RB_GM_CHURCHDEPT_JOB = "O contato da sua guilda com a Igreja: traz gente nova e ajuda a manter a guilda cheia."
	L.RB_GM_CHURCHDEPT_SHOWS = "O badge da Igreja Missionária no retrato e ao lado do nome."
	L.RB_GM_CHURCHDEPT_UNLOCKS = "O título e a sala do departamento. A sala e os números da própria Igreja vêm com a próxima linha."
	L.RB_GM_CHURCH = "Correspondente da Igreja (a aba Igreja)"
	L.RB_GM_CHURCH_JOB = "Responde ao Chefe da Igreja por manter a sua guilda cheia. Nomeia a mesma pessoa da linha de cima."
	L.RB_GM_CHURCH_SHOWS = "Nada no retrato."
	L.RB_GM_CHURCH_UNLOCKS = "A sala da Igreja, os números da aba Igreja, e registrar recrutas que ele trouxe."
	L.RB_GM_BTN_CHURCH = "Abrir a Igreja"
	L.RB_GM_WATCHERS = "Watchers"
	L.RB_GM_WATCHERS_TEXT = "Os seus oficiais já têm a The Watch. Os Watchers também ganham, para os membros abaixo deles."
	L.RB_GM_BTN_WATCHER = "Nomear um Watcher"
	L.RB_GM_CHARTER = "Carta da guilda"
	L.RB_GM_CHARTER_TEXT = "Propósito, idioma, noites de raide e as classes que você procura, públicos por sete dias. Ajuda os recrutas a escolher vocês."
	L.RB_GM_BTN_WRITE = "Escrever"
	L.RB_GM_BANK = "Banco da guilda"
	L.RB_GM_BANK_TEXT = "Abre o banco da guilda uma vez com o addon ligado: ele tira um retrato do estoque e nunca mexe em nada. Você decide se a guilda inteira vê."
	L.RB_GM_BTN_OPEN = "Abrir"
	L.RB_GM_GET = "O que você ganha como mestre da guilda:\n- As asas de bronze no seu retrato, e a marca de bronze ao lado do seu nome.\n- A aba Guilda: esta lista, e a página de cada departamento.\n- Chamados às armas, convocações, decretos reais e inspeções de tabard para a sua guilda.\n- A Agenda da sua guilda, e enquetes do Poll para a sua guilda.\n- A The Watch da sua guilda, com os seus oficiais.\n- As salas Mestres de guilda, Mestres e legates, Mestre e legates, e Mestre e correspondentes."
	L.RB_GM_CLOSE = "Uma regra: o seu poder acaba na porta da sua guilda. Lá dentro, usa bem.\n\nAgora vai lá construir alguma coisa. Bora!"

	L.RB_COUNCIL_TITLE = "O Alto Conselho"
	L.RB_COUNCIL = "Olha só.\n\nAgora você é do Alto Conselho. Isso é enorme. Esse rank não se farma. Você foi escolhido. Não faz a gente se arrepender.\n\nA função: comandar o Bankai Guild comigo. Julgar, chamar o exército, cuidar do lugar.\n\nO que aparece: as asas de prata no seu retrato, e o dragão prateado antes do seu nome no chat. Dá pra pôr um ícone depois dele em Meu perfil, Ícones.\n\nO que você ganha:\n- Decretos reais, inspeções de tabard, chamados às armas e convocações para o exército inteiro.\n- A The Watch: os relatos do conselho, e um voto em cada Julgamento. A palavra final é minha.\n- Até 10 moderadores do Bankai Guild seus.\n- Nomear Apóstolos, e abrir o ranking público da Igreja.\n- Nomear Legates da guilda do Xogum, no Trono.\n- A sala do Alto Conselho.\n\nUma regra: você age pelo Bankai Guild, não pela sua guilda."
	L.RB_COUNCIL_BADGE = "O badge do seu departamento também aparece no seu retrato."
	L.RB_COUNCIL_WAR = "Você chefia a Guerra. Na Sala de Guerra da sua própria guilda você conta como oficial. A sala do seu departamento tem o correspondente de Guerra de cada guilda."
	L.RB_COUNCIL_TREASURY = "Você chefia o Tesouro Federal. A sala do seu departamento tem o Tesoureiro e o correspondente do Tesouro de cada guilda."
	L.RB_COUNCIL_JUSTICE = "Você está no Conselho de Justiça. Quem preside sou eu. Quando eu não estou, um Alto Conselheiro preside. A sala do seu departamento tem o correspondente de Justiça de cada guilda."
	L.RB_COUNCIL_ARTISANRY = "Você chefia os Artesãos. A sala do seu departamento tem o correspondente de Artesãos de cada guilda. As ferramentas próprias do departamento vêm depois."
	L.RB_COUNCIL_HERALDRY = "Você chefia a Heráldica. Você posta a Agenda do Xogum para o exército inteiro. A sala do seu departamento tem o correspondente de Heráldica de cada guilda."
	L.RB_COUNCIL_CHURCHDEPT = "Você chefia o departamento da Igreja. A sala do seu departamento tem o correspondente da Igreja de cada guilda, e o ranking da aba Igreja fica aberto para você."

	L.RB_STEWARD_TITLE = "O meu Senescal"
	L.RB_STEWARD = "E aí,\n\nAgora você é o meu Senescal. Quer dizer que, quando eu não estou, você sou eu. Sem pressão.\n\nA função: manter o Trono funcionando em meu nome.\n\nO que aparece: nenhuma moldura nova. O seu poder fica na aba Trono.\n\nO que você ganha:\n- O Trono, agindo pelo Xogum: chamada, Inspeção Real, a Agenda, o Poll, os portões.\n- Mãos do Xogum suas. Você nomeia, você tira.\n- Os botões e os guardiões do tesouro, e o valor da contribuição semanal.\n- Todo tipo de decreto, para o exército inteiro.\n- A sala do Secretariado, comigo.\n\nO que continua meu: as minhas Mãos, a corte, os mandados e os perdões.\n\nUma regra: age como se eu estivesse olhando. Porque eu vou estar."

	L.RB_HAND_TITLE = "Mão do Xogum"
	L.RB_HAND = "Olha,\n\nEu te fiz Mão do Xogum. Isso é coisa séria. Você usa as minhas ferramentas, em meu nome.\n\nO que aparece: nenhuma moldura nova. A aba Trono abre pra você.\n\nO que você ganha:\n- Convocar os Anciãos: uma chamada de todo Ancião e Membro do Conselho online.\n- Inspeção Real: o exército confere os tabards em volta.\n- A Agenda do Xogum, e as enquetes do Poll.\n- Os portões: para onde os recrutas novos vão.\n- Chamados às armas e convocações para o exército inteiro.\n\nO que continua meu: a lista de Mãos, os mandados, a corte e os perdões.\n\nUma regra: não spamma o exército. Cada chamado seu aparece na tela de todo mundo."

	L.RB_TREASURER_TITLE = "O Tesoureiro Federal"
	L.RB_TREASURER = "E aí,\n\nVocê é o Tesoureiro Federal. Você guarda o ouro do Bankai Guild. Pois é. Todo ele.\n\nA função: manter o tesouro honesto, e num livro só.\n\nO que aparece: a moldura de dragão do Tesoureiro no seu retrato.\n\nO que você ganha:\n- A aba Tesouro e o seu livro: cada troca e carta com ouro ou itens entra sozinha, depois que você aceita compartilhar.\n- A contribuição semanal, paga a você. Quem pagou fica privado: o Xogum e os oficiais de cada guilda veem, o exército nunca.\n- A sala do Alto Conselho e a sala do Tesouro Federal.\n\nO que você ganha jogando é seu. Nunca entra no livro.\n\nUma regra: cada cobre que entra, cada cobre que sai. No livro."

	L.RB_KEEPER_TITLE = "Guardião do tesouro"
	L.RB_KEEPER = "E aí,\n\nEu te nomeei guardião do tesouro. Confio o ouro a você. Não deixa ficar estranho.\n\nA função: guardar parte do tesouro no seu personagem, junto com o Tesoureiro.\n\nO que aparece: nenhuma moldura nova.\n\nO que você ganha:\n- O seu próprio livro na aba Tesouro. Ouro e itens que te dão por troca ou carta contam como doação, sozinhos, depois que você aceita compartilhar.\n- Ouro entre dois guardiões é transferência, nunca doação.\n- O que você ganha jogando continua seu. Venda ou compra entra como não contada.\n\nSão cinco guardiões no máximo, e eu posso tirar quando quiser.\n\nUma regra: ouro doado nunca é seu pra gastar."

	L.RB_LEGATE_TITLE = "Legate"
	L.RB_LEGATE = "Olha só.\n\nAgora você é Legate de <%s>. Bora!\n\nA função: liderar um grupo de raide. Você e até 39 companheiros de guilda que toparam, 40 no total. Leva eles pros eventos, raides e guerras.\n\nO que aparece: o badge de Legate no seu retrato, e o mesmo badge ao lado do seu nome.\n\nO que você ganha:\n- O seu grupo na Sala de Guerra (aba O Reino): designar e tirar soldados, convidar os que estão online pra raide, um chat privado do esquadrão.\n- As salas de mestres e legates no Chat.\n\nNada é automático: nenhum convite, expulsão ou promoção na guilda. Os grupos são opcionais, e o pessoal pode jogar com outro líder.\n\nUma regra: só põe na lista quem disse sim."

	L.RB_CORR_TREASURY_TITLE = "Correspondente do Tesouro"
	L.RB_CORR_TREASURY = "E aí,\n\nAgora você é o correspondente do Tesouro de <%s>. Boa.\n\nA função: manter em ordem os registros do Tesouro e o compartilhamento do banco da guilda, com o mestre da guilda e o Tesouro Federal.\n\nO que aparece: o badge do Tesouro Federal no seu retrato e ao lado do seu nome.\n\nO que você ganha:\n- O banco da sua guilda no addon. Abre o banco da guilda com o addon ligado e ele tira um retrato do estoque. Ele nunca mexe em nada. O mestre da guilda decide se a guilda inteira vê.\n- A sala do Tesouro Federal, e a sala de Mestre e correspondentes.\n\nUma regra: o ouro da guilda é da guilda. Mantém os livros limpos."
	L.RB_CORR_WAR_TITLE = "Correspondente de Guerra"
	L.RB_CORR_WAR = "Olha,\n\nAgora você é o correspondente de Guerra de <%s>. É você quem faz as raides acontecerem.\n\nA função: organizar as raides e as operações JxJ da sua guilda, os grupos de raide e os registros pós-operação.\n\nO que aparece: o badge do Departamento de Guerra no seu retrato e ao lado do seu nome.\n\nO que você ganha:\n- Direitos de oficial na Sala de Guerra da sua guilda (aba O Reino): operações, grupos de raide, postos, registros pós-operação.\n- A sala do Departamento de Guerra, e a sala de Mestre e correspondentes.\n\nTudo isso dentro da sua própria guilda.\n\nUma regra: planeja, chama, e aparece."
	L.RB_CORR_JUSTICE_TITLE = "Correspondente de Justiça"
	L.RB_CORR_JUSTICE = "E aí,\n\nAgora você é o correspondente de Justiça de <%s>. Você mantém a paz.\n\nA função: acompanhar o chat da sua guilda, resolver os problemas, e trabalhar com o mestre da guilda e o Conselho de Justiça.\n\nO que aparece: o badge do Conselho de Justiça no seu retrato e ao lado do seu nome.\n\nO que você ganha:\n- A mesa inteira da The Watch (aba The Watch) para os membros da sua guilda abaixo de você: avisos, castigos, a lista de vigiados, relatos.\n- Quando eu confirmo um caso depois do voto do Alto Conselho, você aplica na sua guilda. O addon nunca expulsa ninguém sozinho.\n- A sala do Conselho de Justiça.\n\nUma regra: seja justo. As mesmas regras valem pros seus amigos."
	L.RB_CORR_ARTISANRY_TITLE = "Correspondente dos Artesãos"
	L.RB_CORR_ARTISANRY = "E aí,\n\nAgora você é o correspondente dos Artesãos de <%s>. O melhor amigo dos artesãos.\n\nA função: ajudar o pessoal da guilda a achar artesãos, e levar pedidos, materiais e suprimentos pra quem precisa.\n\nO que aparece: o badge da Associação dos Artesãos no seu retrato e ao lado do seu nome.\n\nO que você ganha:\n- O quadro de Artesãos, a um clique da sua aba Guilda.\n- A sala da Associação dos Artesãos, e a sala de Mestre e correspondentes.\n\nAs ferramentas próprias do departamento ainda não chegaram. Por enquanto, você é a pessoa pra quem o pessoal pergunta.\n\nUma regra: ninguém da sua guilda fica travado sem um craft."
	L.RB_CORR_HERALDRY_TITLE = "Correspondente de Heráldica"
	L.RB_CORR_HERALDRY = "Olha,\n\nAgora você é o correspondente de Heráldica de <%s>. Você é a voz da sua guilda.\n\nA função: cuidar dos decretos, da Agenda e das convocações da guilda, e fazer o pessoal aparecer nos eventos e nas lives.\n\nO que aparece: o badge do Departamento de Heráldica no seu retrato e ao lado do seu nome.\n\nO que você ganha:\n- Todo decreto para a sua guilda: chamados às armas, convocações, decretos reais, inspeções de tabard.\n- A Agenda da sua guilda.\n- A sala do Departamento de Heráldica, e a sala de Mestre e correspondentes.\n\nSó a sua guilda. O exército inteiro é da Coroa e do Alto Conselho.\n\nUma regra: não grita lobo à toa. Chama quando importa."
	L.RB_CORR_CHURCHDEPT_TITLE = "Correspondente da Igreja Missionária"
	L.RB_CORR_CHURCHDEPT = "E aí,\n\nAgora você é o correspondente de <%s> para a Igreja Missionária.\n\nA função: trazer gente nova, e ajudar a manter a sua guilda cheia.\n\nO que aparece: o badge da Igreja Missionária no seu retrato e ao lado do seu nome.\n\nO que você ganha: o título, e a sala do departamento. Sinceramente, é isso. Ele mostra pra todo mundo quem é o contato da sua guilda com a Igreja.\n\nPara a sala da própria Igreja e os números de recrutamento, você precisa de um lugar na Igreja também. O mestre da guilda nomeia o correspondente da Igreja na aba Igreja, ou um Apóstolo te nomeia missionário.\n\nUma regra: traz jogador novo de verdade. Alts e trocas entre guildas Bankai Guild nunca contam."

	L.RB_CHURCHCORR_TITLE = "Correspondente da Igreja"
	L.RB_CHURCHCORR = "E aí,\n\nAgora você é o correspondente da Igreja de <%s>. Você responde ao Chefe da Igreja. Ou seja, eu.\n\nA função: manter a sua guilda cheia.\n\nO que aparece: nenhuma moldura nova.\n\nO que você ganha:\n- A aba Igreja: o ranking, os seus números, e as pessoas.\n- Registrar um recruta que você trouxe, até 15 em aberto. Ele conta pra você se entrar numa guilda Bankai Guild em até 14 dias e for novo no Bankai Guild.\n- A sala da Igreja no Chat.\n\nO seu ranking é a sequência de dias acima de 950 membros, contada desde a sua nomeação.\n\nUma regra: faz a sua guilda crescer, mas nunca puxando gente de outra guilda Bankai Guild."

	L.RB_WATCHER_TITLE = "Watcher"
	L.RB_WATCHER = "E aí,\n\nO mestre da sua guilda te nomeou Watcher de <%s>. Você ajuda a manter o chat limpo.\n\nA função: ficar de olho no chat da guilda, e entrar em ação quando alguém passa do limite.\n\nO que aparece: nada no seu retrato.\n\nO que você ganha: a mesa inteira da The Watch (aba The Watch) para os membros da sua guilda abaixo de você: avisos, castigos, a lista de vigiados, relatos e casos.\n\nVocê continua Watcher enquanto o mestre da guilda te mantiver na lista dele.\n\nUma regra: avisa primeiro. Os castigos sobem a partir daí: uma hora, um dia, uma semana."

	L.RB_MODERATOR_TITLE = "Moderador do Bankai Guild"
	L.RB_MODERATOR = "Olha só.\n\nAgora você é moderador do Bankai Guild. Você mantém limpo o chat do exército inteiro. Isso é trabalho de verdade.\n\nA função: lidar com abuso, ofensas, spam e golpes nos chats do Bankai Guild.\n\nO que aparece: nada no seu retrato.\n\nO que você ganha:\n- A moderação de chat da The Watch: apagar linhas e dar castigo em qualquer lugar do Bankai Guild, mestres de outras guildas inclusive. Nunca o mestre da <Elfcore>, nem ninguém acima de você.\n- A sala The Watch, com o Alto Conselho, os outros moderadores e eu.\n\nVocê continua enquanto quem te nomeou te mantiver na lista dele.\n\nUma regra: o que você vê no time fica no time."

	L.RB_APOSTLE_TITLE = "Apóstolo"
	L.RB_APOSTLE_1 = "E aí,\n\nAgora você é um dos Doze Apóstolos da Igreja Missionária de Bankai Guild. Doze. Só isso. Isso é enorme.\n\nA função: trazer jogadores novos pro Bankai Guild, e montar uma rede de missionários que façam o mesmo.\n\nO que aparece: os três melhores Apóstolos dos últimos 30 dias usam a cruz dos Apóstolos, e todo mundo vê."
	L.RB_APOSTLE_RED = "No Meu perfil, em Visual, também tem uma cruz vermelha que só você vê."
	L.RB_APOSTLE_2 = "O que você ganha:\n- Até 12 missionários seus (aba Igreja, Nomear, ou clique direito num jogador).\n- A aba Igreja: o ranking, os seus números, as pessoas.\n- A sala dos Apóstolos e as salas da Igreja no Chat.\n- Enquanto você joga, o seu addon guarda o livro da Igreja pra todo mundo.\n\nUma regra: nomeia gente que vai fazer de verdade."

	L.RB_APOSTLE_LAUNCH_TITLE = "A Igreja, no lançamento"
	L.RB_APOSTLE_LAUNCH = "Olha só.\n\nO jogo está no ar. Você é um dos doze Apóstolos do exército inteiro. Isso é enorme. Agora a Igreja mostra pra que veio.\n\nA função é a mesma: trazer jogador novo pro Bankai Guild, e formar missionários que façam o mesmo.\n\n- Nomeia missionários: até 12 cada um, na aba Igreja (Nomear) ou com clique direito num jogador. Eles nomeiam os deles, até cinco níveis abaixo de você. A Igreja inteira vai até 5.000.\n- Pontos: 10 por jogador novo no Bankai Guild que entra por você, mais 5 se ele ainda estiver aqui 7 dias depois. Mais 25%, 10% e 5% do que trazem os seus três níveis abaixo. Alguém abaixo pode passar você. Ótimo. Quer dizer que está funcionando.\n- Trouxe alguém que outro jogador convidou? Registra ele: ele conta se entrar numa guilda Bankai Guild em até 14 dias.\n- Os três melhores Apóstolos dos últimos 30 dias usam a cruz.\n- Alguém parou de jogar? Tira ele. Quem ele nomeou continua no lugar.\n\nUma regra: só jogador novo de verdade. Alts e trocas entre guildas Bankai Guild nunca contam. Pontos são só no jogo, nunca ouro.\n\nDeixa o addon ligado enquanto joga. Ele guarda o livro da Igreja. Bora!"

	L.RB_MISSIONARY_TITLE = "Missionário"
